import type { Course, Lesson, Question } from './types';
const q = (id:string,prompt:string,options:string[],correct:number,explanation:string):Question => ({id,prompt,options,correct,explanation});
const lesson = (courseId:string,id:string,title:string,diagram:Lesson['diagram'],objectives:string[],sections:[string,string][],example:string,terms:string[],checks:Question[],task:string,takeaway:string):Lesson => ({courseId,id,title,minutes:14,diagram,objectives,sections:sections.map(([title,text])=>({title,text})),example,terms,checks,task,takeaway});
export const courses:Course[] = [
{ id:'film-language', title:'Film Language & Visual Storytelling',shortTitle:'The language of cinema',category:'Film language',level:'Beginner',summary:'Read the frame. Discover how shots, angles and the arrangement of a scene build meaning.',color:'#D8A35D',icon:'frame',objectives:['Choose shot sizes for narrative information','Analyze composition without assuming a single meaning','Build a visual story through purposeful detail'],references:[],lessons:[
lesson('film-language','shot-sizes','Thinking in shot sizes','frame',['Distinguish wide, medium and close framing','Justify a change of shot size'],[
['What does the viewer need to know?','A shot is an uninterrupted view between edits. Shot size describes how much of a subject and its surroundings the frame includes. A wide shot can establish where a person is and show relationships within a space. A medium shot balances gesture and surroundings. A close-up isolates a face, hand or object so a small change becomes easier to notice. These labels are practical working descriptions, not measurements with universal boundaries. Frame size also depends on the subject: a close-up of a watch is different from a close-up of a person.'],
['Attention is a choice','Imagine a student waiting outside an examination room. A wide view might reveal the empty corridor and a closed door. A medium view lets us see the student shift a bag between hands. A close-up of a shaking hand gives a different kind of information. None of these automatically means anxiety. Performance, sound, context and shot duration guide that interpretation. Ask what the audience can observe before claiming what the shot means. A close-up may conceal information just as powerfully as it reveals it.'],
['Planning coverage','Coverage is the set of views recorded so a scene can be assembled in editing. Start with the action and its turning point, then decide which views are necessary. A wide master may preserve spatial continuity; closer coverage can emphasize reactions. Shooting every possible angle is expensive and may weaken decision-making. Instead, list the facts each shot must communicate. Keep headroom and looking room intentional, and check whether objects needed later are visible early enough.'],
['From label to decision','Try holding the same action in a wide shot before cutting closer. Notice when you begin to want more detail. That moment is often a useful editing question. On a phone, tiny gestures in a wide shot may be difficult to read, so evaluate the frame at the expected viewing size. A shot list should name both framing and purpose: “close-up, hand stops tapping as door opens” is more useful than “close-up” alone.']
], 'Three-shot study: corridor wide → student medium → fingers close. Reverse the order and the location becomes a reveal rather than an introduction. Compare what is known at each cut.', ['Shot','Wide shot','Close-up'],[q('s1','Which view best establishes a person’s relationship to a room?',['Wide shot','Close-up of an eye','Insert of a key'],0,'A wide shot can show both person and surroundings.'),q('s2','Does a close-up always mean sadness?',['Yes','No; context guides interpretation'],1,'Shot size directs attention, but does not fix emotion.')], 'Photograph one ordinary action in wide, medium and close framing. Write the new information each image adds.','Choose framing by information, not by a fixed emotional formula.'),
lesson('film-language','angles-viewpoint','Camera angles and point of view','frame',['Compare camera height with camera tilt','Explain how context changes an angle’s effect'],[
['Position before meaning','Camera height is its physical elevation; angle describes its orientation toward a subject. An eye-level view can feel observational, a high angle looks down, and a low angle looks up. Height and tilt interact but are not identical. A camera placed high can remain level and frame architecture. A low camera can look straight ahead at a child. Describe the physical setup clearly before interpreting its expressive effect.'],
['Avoid the shortcut','High angles do not always make subjects weak, and low angles do not always make them powerful. A high view may make a crowd legible; a low view may simply reveal a ceiling. A character filmed from below might seem trapped if the surrounding architecture dominates. Meaning comes from scale, performance, lighting, narrative and comparison with adjacent shots. Treat a visual interpretation as an argument supported by details rather than a dictionary translation.'],
['Whose view is this?','A point-of-view shot approximates what a character sees. It often follows a look and may be followed by a reaction, but it need not imitate the precise optics of human vision. An objective view offers a scene without clearly belonging to one character. A film can move between these positions to control knowledge. If we see a hidden letter that the protagonist misses, we know more than that character; if we only see what they see, uncertainty may increase.'],
['Make a controlled comparison','Film a seated subject at three heights, keeping the lighting, action and approximate framing stable. Then change only the tilt. This separates variables and makes observations more reliable. Leave safe clearance for the operator and equipment; an expressive angle is never a reason to balance a camera unsafely. In a storyboard, label the angle and whose experience it supports, then explain the likely effect in this particular scene.']
], 'A child looks up at a door handle. A low camera expresses access and scale; it does not automatically celebrate the handle as powerful.', ['Camera angle','Point of view','Looking room'],[q('a1','A high camera must always tilt down.',['True','False'],1,'Height and tilt are separate choices.'),q('a2','The strongest interpretation uses…',['An angle-to-emotion rule','Visible details and narrative context'],1,'Context makes an interpretation defensible.')], 'Shoot a doorway from high, eye-level and low viewpoints. Give two plausible readings of each.','Describe the camera first; interpret it with evidence.'),
lesson('film-language','mise-en-scene','Composition and mise-en-scène','frame',['Identify elements arranged before the camera','Use contrast and placement to guide attention'],[
['The arranged world','Mise-en-scène concerns the staging of what is placed before the camera: setting, costume, objects, lighting, performance and spatial arrangement. Composition concerns how elements relate inside the image. These areas overlap in practice. A brightly colored scarf, an actor’s movement and a doorway can all guide attention. Instead of naming objects at random, ask how their arrangement supports a moment in the story.'],
['Balance and emphasis','The rule of thirds is a useful compositional guide that divides a frame into nine areas, but it is not a rule of quality. Centered composition may suggest formality or confrontation. Negative space may create room for an anticipated entrance. Contrast can be produced by brightness, color, focus, scale or movement. When several elements compete, decide which one should be noticed first and simplify the others. Good composition is a hierarchy of attention, not a collection of decorative rules.'],
['Space as storytelling','Place two people at opposite ends of a table. Their distance is observable, while “emotional separation” is an interpretation that needs context. Bringing them closer may alter the scene without a line of dialogue. Foreground objects can partly conceal a person, and doorways can create frames within frames. Check whether the arrangement remains readable when actors move. A beautiful still frame that blocks an essential action may not work as a film shot.'],
['Analyze and revise','Build a small scene with a chair, a cup and a person. First distribute attention evenly; then make the cup the most noticeable element without moving the camera. Change light, contrast or performance. Compare the results and explain what you changed. In analysis, distinguish observation (“the cup is brightest”) from inference (“we may expect it to matter”). That distinction keeps your writing precise and allows alternative interpretations.']
], 'In an original scene, an untouched cup sits in a bright patch while a figure waits in shadow. When the figure leaves, the cup remains: an ordinary prop becomes a visual trace.', ['Mise-en-scène','Negative space','Rule of thirds'],[q('m1','Which belongs to mise-en-scène?',['Costume and blocking','Only the export codec'],0,'Costume and blocking are staged elements.'),q('m2','Must a strong frame obey thirds?',['Yes','No'],1,'Centered, asymmetric and other arrangements can be purposeful.')], 'Create two frames with the same objects but different centers of attention. Explain the changes.','Composition guides attention; interpretation still depends on context.')],quiz:[q('fl1','Which framing most clearly reveals a small hand gesture?',['Wide','Close-up','Extreme wide'],1,'Closer framing makes small detail legible.'),q('fl2','A high angle always signals weakness.',['True','False'],1,'Its effect depends on context and staging.'),q('fl3','Which is an observation rather than an inference?',['She is lonely','The room is empty except for one chair','The chair symbolizes defeat'],1,'The chair count is visible evidence; the other claims interpret it.'),q('fl4','Why plan coverage?',['To record every imaginable view','To provide purposeful material for editing','To avoid thinking about performance'],1,'Coverage should support action and editorial choices.'),q('fl5','Negative space is…',['An unused error','Relatively unoccupied area that can shape attention','Only black pixels'],1,'Empty areas can create balance, isolation or anticipation.') ]},
{ id:'cinematography',title:'Fundamentals of Cinematography',shortTitle:'Light, lens & exposure',category:'Cinematography',level:'Beginner',summary:'Turn camera settings into deliberate choices about light, movement and depth.',color:'#35BDB5',icon:'camera',objectives:['Balance exposure settings and their tradeoffs','Distinguish focal length from perspective','Plan simple motivated lighting'],references:[{title:'Nikon: A Basic Look at the Basics of Exposure',url:'https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/a-basic-look-at-the-basics-of-exposure'}],lessons:[
lesson('cinematography','exposure-triangle','Exposure: three connected decisions','exposure',['Predict the effect of one-stop changes','Identify blur, depth and noise tradeoffs'],[
['Light and recorded brightness','Exposure begins with the light reaching a sensor or film. Aperture controls the lens opening and shutter time controls how long light is collected per frame. ISO describes the camera’s sensitivity rating or signal handling; its implementation varies across digital cameras. Raising digital ISO does not create more scene light. For practical learning, separate captured light from the displayed brightness of the image. Two images can look equally bright while differing in noise and motion rendering.'],
['Stops and aperture','A stop is a doubling or halving of light or exposure-related signal level. Opening from f/4 to about f/2.8 admits approximately twice as much light when other factors remain fixed. Smaller f-numbers describe wider openings. A wider aperture usually gives shallower depth of field for a fixed setup, but subject distance, focal length, format and viewing conditions also matter. Do not treat aperture as a background-blur slider independent of the scene.'],
['Time and motion','A longer shutter time lets more light reach the sensor and can increase motion blur. At 24 frames per second, 1/48 second is a common starting point associated with a 180-degree shutter, not a universal requirement. A faster shutter may render movement more sharply; it can also make movement feel staccato. Frame rate limits the available exposure time per frame. Under artificial lighting, some settings may cause flicker, so test the actual location.'],
['A decision process','Choose frame rate and desired motion rendering first, then aperture for depth and lens behavior, then manage brightness with light levels, neutral-density filtration and appropriate ISO. Examine highlights, shadows and subject visibility rather than trusting the monitor alone. Histogram and waveform tools can help, but their interpretation depends on the recording format. The lab is deliberately illustrative: real dynamic range, sensor response and lens transmission are not calibrated by its controls.']
], 'At fixed lighting and ISO, changing f/4 to f/2.8 gains about one stop. Changing 1/50 to 1/100 loses one stop. Together they approximately preserve brightness while changing depth and motion.', ['Aperture','Shutter speed','ISO'],[q('e1','f/2.8 admits more light than f/4 at equal settings.',['True','False'],0,'The wider opening admits approximately twice the light.'),q('e2','A longer shutter time generally…',['Reduces motion blur','Increases motion blur'],1,'A moving subject travels farther during the exposure.')], 'In the exposure lab, preserve similar brightness using two different combinations. Record which tradeoffs changed.','Similar brightness does not mean equivalent images.'),
lesson('cinematography','lenses-depth','Lenses, perspective and depth','frame',['Separate focal length from camera distance','Predict depth-of-field changes for a fixed setup'],[
['What focal length changes','Focal length is an optical property of a lens, commonly stated in millimeters. On a given sensor format, a shorter focal length gives a wider angle of view, while a longer one gives a narrower view. Sensor size matters: the same focal length does not produce identical framing on every format. Avoid describing a lens as simply “wide” without considering the imaging area. Lens choice also affects practical matters such as minimum focus distance and available aperture.'],
['Perspective comes from position','Perspective describes the apparent spatial relationships between objects at different distances. Camera position determines these relationships. If the camera stays still and the focal length changes, the framing changes; cropping the wider view can approximate the narrower perspective. The familiar compressed look of a distant subject often occurs because the camera is moved farther away to keep similar framing with a longer lens. Attribute that spatial change to distance, not a magical property of focal length alone.'],
['Depth of field','Depth of field is the range judged acceptably sharp around the focus distance. There is no absolute boundary where sharp instantly becomes unsharp. Aperture, focal length, focus distance, format and final viewing conditions influence the judgment. In a fixed setup, stopping down usually increases depth of field, and moving closer usually reduces it. Focus is a creative and technical decision: a beautiful soft background is unhelpful if the important action falls outside the sharp region.'],
['Choose for the scene','Before changing a lens, ask where the camera can safely stand, how much space the scene needs and whether focus can be maintained during movement. Try a wide view close to a subject and a longer view from farther away with similar subject size. Compare background scale and the apparent distance between objects. Do not judge distortion from a single face alone; include foreground and background markers. Record camera distance so the experiment is reproducible.']
], 'Photograph a person with a tree behind them. Keep the person equally large by backing away with a longer focal length. The tree appears relatively larger because the viewpoint changed.', ['Focal length','Depth of field','Perspective'],[q('l1','What primarily determines perspective?',['Camera position','ISO'],0,'Position sets relative viewing geometry.'),q('l2','At a fixed setup, stopping down usually…',['Increases depth of field','Always blurs everything'],0,'A smaller aperture generally expands acceptable sharpness.')], 'Make a two-image distance-and-lens comparison. Label which variables you changed.','Separate the lens’s field of view from the camera’s viewpoint.'),
lesson('cinematography','lighting-color','Lighting a motivated scene','exposure',['Compare hard and soft light','Plan key, fill and color choices from a source'],[
['Begin with a source','Motivated lighting looks as though it could come from a believable source in the scene: a window, a desk lamp or an overhead fixture. The actual film light may be outside the frame and stronger than the visible source. Motivation is a storytelling decision, not a requirement that every source be literally visible. Decide the time of day, what a character is doing and which areas need to be readable before adding equipment.'],
['Quality and direction','Hard light produces relatively defined shadow edges; soft light produces more gradual transitions. Apparent source size relative to the subject is central: a large nearby diffuser can soften light, while the same source far away appears smaller. Direction shapes faces and surfaces. Moving a light to the side may reveal texture and create contrast; frontal light can reduce visible modeling. Neither is universally better. Compare the result against the purpose of the scene.'],
['Contrast and color','The key is the principal shaping light, while fill reduces shadow contrast. Negative fill uses a dark surface to reduce reflected light. A backlight can separate a figure but is not compulsory. Color temperature is one description of light color, and white balance influences how it is recorded. Mixed sources may remain visibly different after white balance. Decide whether those differences support the scene, and test skin tones and important materials under the actual lights.'],
['Work safely and simply','Start with one window and a reflector. Move the subject and reflector before adding more sources. Protect exits, secure stands, keep liquids away from electricity and use rated equipment; beginners should not improvise mains wiring. Record the light direction and exposure settings so matching shots remain consistent. A lighting diagram is a communication tool: label source position, subject, camera and intended effect. Evaluate both shadow shape and highlight clipping before calling the setup finished.']
], 'For a late study scene, a desk lamp motivates a side key. A pale card on the opposite side gently lifts shadows. Removing the card increases contrast without changing the principal source.', ['Key light','Fill light','Color temperature'],[q('li1','A larger apparent source usually produces…',['Softer shadow edges','Harder shadow edges'],0,'Relative source size affects shadow transition.'),q('li2','Is backlight compulsory?',['Yes','No'],1,'Use separation only when it serves the image.')], 'Draw a safe one-source lighting plan. Compare the scene with and without reflected fill.','Shape light deliberately before adding more lights.')],quiz:[q('c1','Opening f/4 to f/2.8 gives approximately…',['One stop more light','One stop less light','No change'],0,'Each full aperture stop changes light by about a factor of two.'),q('c2','At fixed framing setup, longer shutter time generally adds…',['Motion blur','Resolution','Focal length'],0,'Movement is integrated for longer.'),q('c3','Raising ISO creates scene light.',['True','False'],1,'It changes rating or signal processing, not illumination.'),q('c4','Perspective changes primarily when…',['The camera position changes','The file name changes','ISO changes'],0,'Viewpoint determines relative geometry.'),q('c5','A reflector opposite the key can…',['Reduce shadow contrast','Change the focal length','Double frame rate'],0,'Reflected fill adds light to shadows.') ]},
{ id:'editing',title:'Film Editing & Continuity',shortTitle:'The invisible cut',category:'Editing',level:'Beginner',summary:'Connect space, shape time and discover why the right cut feels inevitable.',color:'#A8B8DF',icon:'scissors',objectives:['Maintain readable screen geography','Choose cuts for information and rhythm','Distinguish continuity from deliberate disruption'],references:[],lessons:[
lesson('editing','continuity-axis','Continuity and the 180-degree axis','axis',['Identify a line of action','Predict screen direction after crossing it'],[
['Continuity as orientation','Continuity editing helps viewers understand where people are and how actions connect. It is not simply hiding every cut. A viewer can notice an edit yet remain spatially oriented. Establishing views, consistent eyelines, matched action and stable screen direction all contribute. Before shooting, sketch the positions of the characters and ask which information the audience needs. A continuity plan can prevent expensive repairs after a location is no longer available.'],
['The shared axis','For a conversation, an imaginary line between two subjects often serves as the axis of action. Keeping camera positions on one side generally preserves their left-right screen relationship. Crossing to the other side can reverse that relationship. The 180-degree rule is a practical convention, not a law forbidding expressive filmmaking. A moving character or a new interaction can change the relevant line, so the axis must be understood in relation to the current action.'],
['Eyelines and matching','In complementary close views, one subject might look screen right and the other screen left. This helps suggest that they face one another. Camera height, look direction and subject position must be considered together. Match-on-action cuts connect movement across views, often allowing the viewer to follow the action despite a camera change. Record enough overlap in performance so the editor can choose the exact cutting point. Small mismatches may matter less than a convincing emotional transition.'],
['Crossing with intention','A crossing can be made legible by showing camera movement across the line, including a neutral view along it, or reestablishing geography with a wider shot. None is an automatic repair for every scene; judge the resulting sequence. Deliberate disorientation can serve a story, but the effect should be chosen, not discovered accidentally. In the axis lab, compare consistent and reversed direction, then describe what additional shot might help a viewer follow the change.']
], 'Two classmates face each other across a table. Camera A keeps the first on screen left. Switching across the table reverses their positions; a wide reestablishing view can help explain the new orientation.', ['Axis of action','Eyeline match','Match on action'],[q('ax1','Staying on one side usually preserves…',['Screen direction','The same lens'],0,'The left-right relationship tends to remain stable.'),q('ax2','Can the axis be crossed intentionally?',['Yes','Never'],0,'A filmmaker can establish or deliberately disrupt orientation.')], 'Storyboard a conversation with three consistent views and one deliberate crossing. Explain the transition.','Continuity serves comprehension; breaking it should serve a purpose.'),
lesson('editing','cuts-transitions','Cuts and transitions with a purpose','sequence',['Choose a transition for a narrative task','Distinguish sound overlap from picture transition'],[
['The cut as a relationship','A cut immediately replaces one image with another. Its meaning depends on both shots and their context. A reaction can reinterpret an earlier action; an insert can disclose a clue. Before adding a transition effect, ask what information or feeling changes at this point. A simple cut often communicates the change efficiently. The presence of a visible effect does not make an edit more professional.'],
['Useful cutting patterns','A cutaway leaves the principal action for related detail. An insert emphasizes a specific element within the action, such as a hand unlocking a door. Crosscutting alternates lines of action, often suggesting a relationship in time or theme; it need not prove that events are simultaneous. A jump cut makes a discontinuity conspicuous, often by removing time within a similar view. A graphic match connects images through shape, movement or composition. These are descriptive tools rather than a checklist every sequence must use.'],
['Sound across the boundary','A J-cut brings the sound of the next scene in before its picture. An L-cut lets sound from the previous scene continue over the next image. The names refer to the arrangement of picture and sound on an editing timeline. Such overlaps can guide attention or soften a scene change without a picture dissolve. They should also preserve intelligibility: competing dialogue may distract if levels and timing are not carefully managed.'],
['Dissolves and fades','A dissolve overlaps the outgoing and incoming images over time; a fade moves to or from a uniform field, often black. These may suggest time passage, closure or association, but their meaning is contextual. Test a straight cut before choosing a dissolve. Watch the full sequence with sound and consider whether the transition creates an unintended relationship. Keep a version of the earlier edit so you can compare decisions instead of judging each change in isolation.']
], 'Hear rain before cutting from a dry room to a wet street: the incoming sound anticipates the new scene. This is a J-cut even though the picture changes with a straight cut.', ['J-cut','L-cut','Dissolve'],[q('ct1','Next-scene sound before its picture is a…',['J-cut','L-cut'],0,'Incoming audio leads the image.'),q('ct2','A dissolve always means a dream.',['True','False'],1,'Transition meaning depends on context.')], 'Edit the same scene change with a straight cut, J-cut and dissolve. Explain which serves the scene best.','Transitions connect ideas; effects alone do not create meaning.'),
lesson('editing','rhythm-time','Pacing, rhythm and screen time','sequence',['Compare shot duration with perceived pace','Use an ellipsis without losing necessary information'],[
['Duration is only one variable','Pacing describes the experienced rate of a sequence’s development. Average shot length can be measured, but it does not fully describe pace. A long shot with complex action can feel urgent, while short static views may feel repetitive. Performance, movement, sound, information and audience expectation all contribute. Ask whether the sequence gives viewers enough time to notice the information that matters.'],
['Rhythm and attention','Editing rhythm concerns patterns of duration, movement, sound and emphasis. Repetition creates expectations; a change can become significant. Cutting every time a musical beat occurs may create regularity but can also flatten dramatic emphasis. Try cutting on an action, a thought or a change in attention. When a character receives news, a held reaction may be more revealing than a fast series of shots. Observe where your attention goes before deciding where to cut.'],
['Compressing and expanding','An ellipsis omits part of story time. Showing someone leave a room and then arrive at a station may remove an uneventful journey. The audience needs enough cues to infer the missing interval. Conversely, editing can expand a brief event through repeated or overlapping views. These are choices about story emphasis, not neutral records of real time. State what the viewer must understand about order and duration before removing connecting material.'],
['Review the whole','Make two versions of a short sequence: one that preserves pauses and one that compresses them. Compare what you learn about the character in each. Watch without music to reveal whether the picture sequence carries its own logic; then restore sound and judge the relationship. Invite a viewer to describe what happened instead of asking only whether they liked it. Their account may reveal confusing geography or missing causal information.']
], 'A kettle, a clock and a waiting face can suggest an extended wait. Shortening every shot may instead suggest restless attention. The images remain the same while the temporal experience changes.', ['Pacing','Rhythm','Ellipsis'],[q('r1','Do shorter shots always feel faster?',['Yes','No'],1,'Action and information also determine perceived pace.'),q('r2','An ellipsis…',['Omits story time','Adds a color filter'],0,'The viewer infers an interval not shown.')], 'Create two 20-second versions of a waiting scene. Keep the source shots but change their durations.','Edit for attention and dramatic change, not a fixed shot-length formula.')],quiz:[q('ed1','The axis convention mainly supports…',['Spatial orientation','Higher resolution','Color grading'],0,'Consistent direction helps locate subjects.'),q('ed2','Incoming scene audio leads picture in a…',['J-cut','L-cut','Fade'],0,'A J-cut introduces the next sound early.'),q('ed3','Match on action connects…',['An action across views','Only matching colors','Two file names'],0,'Continuous action helps bridge a change of viewpoint.'),q('ed4','An ellipsis removes…',['Part of story time','All sound','The need for context'],0,'Viewers infer the omitted interval.'),q('ed5','Pace depends only on shot length.',['True','False'],1,'Motion, sound and information also shape pace.') ]},
{ id:'direction',title:'Film Direction & Storyboarding',shortTitle:'From script to screen',category:'Direction',level:'Beginner',summary:'Find the dramatic intention, stage the action and turn your decisions into a shootable plan.',color:'#DF967B',icon:'clapper',objectives:['Translate a scene into observable actions','Plan readable blocking and coverage','Communicate through shot lists and boards'],references:[],lessons:[
lesson('direction','directors-vision','A director’s vision begins with action','frame',['Identify a scene’s dramatic change','Turn abstract emotion into playable action'],[
['Read for change','A director coordinates creative decisions so a film’s parts support a coherent experience. Begin script analysis with what changes: a person learns something, loses an opportunity or decides to act. Summarize the scene before inventing elaborate camera movement. A useful question is “what does each character want from the other right now?” This turns a general theme into a practical dramatic relationship that can be rehearsed and photographed.'],
['Playable action','An instruction such as “be sad” names an emotional result but may not help an actor perform it. An action such as “hide the letter before your friend sees it” gives a concrete task and a relationship. Discuss circumstances, objectives and obstacles with performers, and allow them to propose behavior. Avoid assuming that one directing vocabulary works for everyone. Rehearsal is a conversation in which observable choices are tested against the scene’s intention.'],
['A coherent treatment','A director’s treatment describes the proposed approach to performance, camera, sound, editing and design. It should connect choices to the material. “Use warm colors” is incomplete unless you explain why, where and how that choice develops. Build comparisons using original sketches, diagrams or media you have permission to share. A treatment is not a guarantee that every planned image will survive production; it is a decision framework for adapting intelligently.'],
['Collaboration and responsibility','The director works with cinematography, design, sound, editing and production colleagues. Communicate priorities clearly: which moment cannot be lost if time runs short? Protect performer consent and set safety, and agree boundaries before sensitive action. No shot justifies unsafe or coercive behavior. After rehearsal, revise the plan to fit the performers and location. A clear vision becomes more useful when others can understand its purpose and contribute their expertise.']
], 'A character says “stay” while moving a second chair toward the table. The action gives the performer and camera a specific relationship to work with, beyond an instruction to “look emotional.”', ['Objective','Obstacle','Treatment'],[q('d1','Which is more playable?',['Be interesting','Keep your friend from leaving'],1,'It gives the actor an actionable objective.'),q('d2','A treatment should connect style to…',['The material and intention','Random visual trends'],0,'Choices need a reason within the project.')], 'Write a 150-word treatment for a two-person disagreement, naming the change and three practical choices.','Make an intention concrete enough for collaborators to act on.'),
lesson('direction','blocking-space','Blocking actors and the camera','axis',['Map movement around a turning point','Coordinate actor and camera positions'],[
['Movement with a reason','Blocking is the planned arrangement and movement of performers within the scene. It can reveal relationships, conceal information and create opportunities for camera coverage. Begin with what the characters are trying to do. A person may stand to end a conversation or move closer to speak privately. Movement added only to make the frame busy can distract from a scene’s central action.'],
['Map the location','Draw a top-down plan with doors, furniture, performers and camera positions. Mark entrances, exits and important props. Then rehearse the action in the actual space if possible. A doorway that looks generous on paper may be too narrow for an operator and performer to pass safely. Keep walkways clear, respect location rules and coordinate movement with the crew. The diagram helps everyone see practical problems before recording begins.'],
['Blocking and coverage','As performers move, the relevant axis may shift. A camera plan must maintain or deliberately reestablish orientation. Look for frames that contain meaningful action rather than cutting automatically between speakers. A listener’s reaction may be the most important event while the other person talks. Record enough performance overlap for editing, and track prop positions, gestures and eyelines so different takes can connect. Continuity should support performance rather than turn actors into rigid machines.'],
['Rehearse and revise','Run a rehearsal focused on movement, then one with camera and sound positions. Listen for clothing noise, footsteps and obstructed microphone paths. Adjust marks so performers can play the action naturally. A mark is a repeatable position, not an emotional instruction. After each adjustment, check what the viewer will understand. If a key decision happens behind another actor’s shoulder, a small change of position may solve more than another camera angle.']
], 'During an apology, one person stays at the door while the other clears a chair. The space offers an invitation; a later step into the room becomes the scene’s visible change.', ['Blocking','Mark','Coverage'],[q('b1','Blocking concerns…',['Performer positions and movement','Only lens choice'],0,'Camera movement is coordinated with this staging.'),q('b2','Should movement be tested with sound positions?',['Yes','No'],0,'Boom access and movement noise affect the plan.')], 'Draw a floor plan of a small room and block a scene in which someone changes their mind about leaving.','Stage a dramatic change, then choose the views that make it readable.'),
lesson('direction','storyboard-planning','Storyboards and practical shot lists','sequence',['Write actionable shot cards','Estimate a sequence’s screen duration'],[
['A plan for communication','A storyboard represents planned shots as a sequence of images with notes. Drawing ability is secondary to clarity: simple figures, arrows and labels can communicate the essential idea. A shot list is a written production plan and may include framing, angle, action, sound, lens and equipment. Neither document replaces rehearsal. Their job is to make assumptions visible so collaborators can discuss what is necessary and what may be simplified.'],
['What a card needs','Give each shot a stable number and a short title. State shot size and angle, then describe the observable action. Separate action from dialogue or sound notes. Estimate duration if it helps plan rhythm, while recognizing that performance will change it. “Medium, eye level: Mira places the key on the table; hold through the other person’s reaction” is more actionable than “dramatic shot.” Include the purpose when a view might otherwise seem redundant.'],
['Sequence and shooting order','Storyboard order follows the audience’s experience; shooting order often follows location, lighting or performer availability. Preserve stable shot identifiers when the production schedule changes. Check that essential screen direction, entrances and prop interactions connect. Do not use a board to force a performance into a plan that no longer fits. Update it after discoveries and explain changes to the crew. A living plan is more useful than a polished document nobody trusts.'],
['Use the studio','Create a small board in the local storyboard studio. Add a wide establishing shot, a medium action and a close reaction, then reorder them to compare information flow. Enter durations and inspect the total. Export JSON as an editable backup; print the board for a readable production handout. Data stays in this browser unless exported. Keep backups before clearing storage, and use non-sensitive production notes in a shared browser.']
], 'Wide: a locked room, 4 s. Close: key turns, 2 s. Medium: door opens to an empty chair, 5 s. Total planned screen time is 11 s, excluding any extra transitions.', ['Storyboard','Shot list','Screen duration'],[q('sb1','A useful action description is…',['Something emotional happens','A hand sets a key on the table'],1,'It describes photographable behavior.'),q('sb2','Must shooting order equal screen order?',['Yes','No'],1,'Production efficiency often changes recording order.')], 'Build a five-shot silent scene in the studio. Export it, then revise the order and compare the meaning.','A useful board explains what to record and why it belongs.')],quiz:[q('di1','A scene objective describes…',['What a character wants now','The sensor size','The release date'],0,'An objective makes the dramatic relationship actionable.'),q('di2','Which instruction is playable?',['Be sad','Prevent your friend reading the letter','Be cinematic'],1,'It specifies an action and obstacle.'),q('di3','A floor plan helps coordinate…',['Actors, camera and sound','Only typography','Only distribution'],0,'It exposes spatial and practical relationships.'),q('di4','Shot identifiers should…',['Remain stable across schedule changes','Always be removed','Replace all action notes'],0,'Stable identifiers prevent production confusion.'),q('di5','A storyboard is…',['An immutable contract','A revisable communication plan','An accredited certificate'],1,'The board supports discussion and adapts to discoveries.') ]},
{ id:'sound-production',title:'Sound & Film Production',shortTitle:'Listen to the scene',category:'Sound & production',level:'Beginner',summary:'Understand the soundtrack, record intelligible dialogue and organize a small production.',color:'#B5C797',icon:'audio',objectives:['Analyze sound’s relationship to story space','Record cleaner location dialogue','Coordinate a practical production workflow'],references:[],lessons:[
lesson('sound-production','sound-worlds','Diegetic sound and the listening world','sound',['Distinguish sound sources in story space','Describe perspective and offscreen sound'],[
['Where does sound belong?','Diegetic sound belongs to the story world: dialogue, footsteps or music playing from a visible or implied radio. Nondiegetic sound comes from outside that world, such as an underscore that the characters do not hear. The distinction concerns narrative status, not whether a sound was recorded on location. A footstep recreated later can still be diegetic. A film may deliberately blur these boundaries or change the status of a piece of music.'],
['Beyond the visible frame','Offscreen sound can establish space without showing its source. Traffic through a window suggests a street, while a knock creates an expectation about the door. Sound perspective concerns perceived distance and position. A nearby whisper should usually differ from a distant voice in level, detail and reverberation. These differences may be exaggerated or altered for expressive reasons, but a convincing sound world requires deliberate relationships rather than maximum loudness for every element.'],
['Layers of a soundtrack','Dialogue carries speech; ambience creates an environmental bed; effects give events detail; music can shape expectation and rhythm. These layers compete for attention. If an essential line is masked, lowering music may be more effective than raising everything. Silence in cinema is often a relative reduction of sound rather than digital zero. A quiet background may make a small object suddenly noticeable. Describe what is audible before interpreting how it affects a scene.'],
['Listening as analysis','Close your eyes during a short sequence you have permission to use and map the sources. Then watch the picture and compare what you inferred. Did sound reveal an unseen space, guide a cut or make an ordinary action ominous? Avoid claiming every viewer will respond identically. Support your reading with timing, source and level relationships. When making a film, plan these relationships early so production can collect the material the edit needs.']
], 'A song begins thin and distant from a character’s radio, then expands into a full score as the scene changes. Its narrative status can shift even though the melody continues.', ['Diegetic sound','Nondiegetic sound','Ambience'],[q('so1','A recreated footstep can be diegetic.',['True','False'],0,'It belongs to the story world even if made later.'),q('so2','Offscreen sound must have a visible source.',['True','False'],1,'Its source can remain outside the image.')], 'Create a sound map for a one-minute waiting scene, separating dialogue, ambience, effects and music.','Classify sound by its relationship to the story, not its recording method.'),
lesson('sound-production','recording-dialogue','Recording intelligible dialogue','sound',['Choose placement before increasing gain','Plan room tone and monitoring'],[
['Distance matters','A microphone records a mixture of the wanted voice, surrounding noise and reflections. Moving it appropriately closer often improves the direct voice relative to the room more effectively than raising recording gain. Gain increases the recorded signal, including unwanted sound; it cannot selectively recover a distant voice. Choose a position that is close enough for clarity while staying out of the frame and respecting the performer’s movement and consent.'],
['Choose and monitor','A boom-mounted directional microphone can follow dialogue above or below the frame. A lavalier can maintain proximity but may pick up clothing rustle. Directional microphones do not erase all unwanted sound, and reflections can still be problematic. Monitor through headphones during rehearsal and takes. Listen for wind, handling noise, interference, clipping and changes when performers turn their heads. A visible waveform alone cannot tell you whether the words are intelligible.'],
['Leave headroom','Set levels using the loudest expected performance, leaving room below digital clipping. Exact targets depend on equipment and workflow, so follow the recorder’s metering guidance and test. Once clipped at an input stage, a signal may be damaged even if a later meter looks acceptable. Record cleanly rather than planning to fix everything with noise reduction. Use suitable wind protection outdoors and secure cables so movement does not pull equipment or create trip hazards.'],
['Collect the missing pieces','Record room tone: a stretch of the location’s background with the set quiet and the setup unchanged. Capture wild lines or isolated effects when needed, and label files with scene and take information. Room tone helps smooth edits but cannot perfectly match every noisy situation. Back up recordings promptly and check that files open. At the end of a take, sound should have a clear way to report a problem before everyone changes position.']
], 'If a voice is buried under a fan, increasing gain raises both. Stop the fan when safe and permitted, move the microphone appropriately, or choose a quieter location before relying on software.', ['Gain','Clipping','Room tone'],[q('re1','Raising gain removes room noise.',['True','False'],1,'It raises wanted and unwanted signal together.'),q('re2','Why record room tone?',['To help bridge dialogue edits','To replace all acting'],0,'A consistent background can smooth edited gaps.')], 'Record the same sentence at two distances in a quiet room. Compare intelligibility with headphones.','Solve recording problems at the source whenever possible.'),
lesson('sound-production','crew-workflow','A small production that stays organized','sequence',['Distinguish production phases','Plan roles, checks and backups'],[
['Before recording','Preproduction turns an idea into a workable plan. Develop the script, permissions, schedule, locations, equipment needs and safety arrangements. On a small student shoot, people may hold several roles, but responsibilities still need owners. Someone must track time, someone must monitor sound and someone must confirm media is recorded. Avoid a plan that assumes one person can perform incompatible tasks simultaneously.'],
['On set','Production is the recording phase. The director works on performance and creative intention; cinematography handles the image; sound records and monitors audio; production coordination manages logistics. Role names vary with project scale. Agree a concise take procedure so camera, sound and performers know when recording begins and ends. Log useful takes and technical problems. A clear report prevents the editor from guessing whether missing dialogue or a soft image was intentional.'],
['After the shoot','Postproduction includes media organization, picture editing, sound work, color finishing and delivery. Preserve original media and edit with working copies where practical. Keep more than one verified copy on separate devices before erasing cards. A backup that has never been checked may not be usable. File names, folders and take notes should be consistent enough for another person to understand. Version edits so a revision does not destroy the only earlier cut.'],
['Responsibility across phases','Get permission for locations, performances and materials you intend to publish. Explain to participants how the work will be used, especially when filming real people. Avoid treating a public location as automatic consent for every use. Schedule breaks, make transport realistic and respect equipment limits. For a classroom project, a smaller achievable scene with clean sound and a clear workflow often teaches more than an ambitious plan that cannot be completed safely.']
], 'A three-person team can rotate camera, performance and sound between setups, but should not expect a speaking actor to monitor dialogue through headphones during the take.', ['Preproduction','Production','Postproduction'],[q('w1','When should recording roles be agreed?',['Before the take','Only after editing'],0,'Responsibilities need to be clear while recording.'),q('w2','A backup should be…',['Verified as readable','Assumed good if copied'],0,'Checking prevents discovering a corrupt copy too late.')], 'Write a one-page plan for a three-person shoot, including role changes, take logging and media backup.','Small crews still need explicit responsibilities.')],quiz:[q('sp1','Diegetic sound belongs to…',['The story world','Only postproduction','Only music'],0,'Narrative status defines the category.'),q('sp2','Increasing gain improves voice-to-room ratio by itself.',['True','False'],1,'Both voice and room are amplified.'),q('sp3','Room tone is useful for…',['Smoothing sound edits','Changing lens angle','Increasing resolution'],0,'It provides a matching environmental bed.'),q('sp4','Location permissions belong primarily in…',['Preproduction','Only the final export','The trailer'],0,'Resolve permissions before recording.'),q('sp5','Before clearing recording media, keep…',['Verified separate backups','Only a renamed file','No copies'],0,'Separate checked copies reduce loss risk.') ]},
{ id:'research',title:'Film Studies & Research Methods',shortTitle:'Watch, question, investigate',category:'Research',level:'Intermediate',summary:'Turn careful observation into a focused argument with evidence and responsible research.',color:'#C4A9D7',icon:'research',objectives:['Separate description from interpretation','Design focused research questions','Evaluate evidence and cite transparently'],references:[{title:'Purdue OWL: Quoting, Paraphrasing, and Summarizing',url:'https://owl.purdue.edu/owl/research_and_citation/using_research/quoting_paraphrasing_and_summarizing/index.html'}],lessons:[
lesson('research','close-reading','Close reading a moving image','research',['Separate observation and interpretation','Support a claim with a formal detail'],[
['Watch in layers','Close reading is sustained attention to how a film produces meaning through form and context. Begin by watching a sequence as a whole, then revisit it with narrower questions about framing, staging, editing and sound. Record timestamps and concrete details. A first impression is useful as a starting point, but it becomes an argument only when you can show how features of the work support it.'],
['Description and interpretation','Description states what can be observed: a character occupies the edge of the frame, a sound continues after a cut, or a reaction lasts longer than preceding shots. Interpretation proposes significance: the framing may make the character seem excluded. These statements are related but not identical. Another viewer may offer a different reading supported by the same material. Strong analysis considers context and does not turn one technical feature into a universal emotional code.'],
['Build a small argument','Choose a claim limited enough to demonstrate in a short passage. Use a sequence of evidence, explanation and qualification. For instance, a waiting scene may create uncertainty by withholding the reverse view of a doorway while repeated offscreen footsteps approach. Identify exactly when the relevant sound and image occur. Do not merely list techniques; explain the relationship between them and the information available to the audience.'],
['Context and limits','Formal analysis can be enriched by historical, industrial or cultural context, but those claims require reliable sources. Avoid guessing a director’s private intention from the image alone. You can argue what the film makes available to viewers without claiming access to the maker’s mind. When writing for assessment, distinguish your close reading from claims borrowed from scholarship. A careful, limited argument is more persuasive than a sweeping statement about all audiences or all cinema.']
], 'Observation: the reverse angle of the corridor is withheld for 18 seconds. Interpretation: the delayed view may sustain uncertainty about who is approaching. The timestamp supports a specific claim, not a universal response.', ['Close reading','Formal analysis','Interpretation'],[q('cr1','“The shot lasts 12 seconds” is…',['Observation','A claim about everyone’s emotion'],0,'It describes a measurable property.'),q('cr2','Can an image alone prove a director’s private intention?',['Yes','No'],1,'Intention requires additional evidence.')], 'Analyze 30 seconds of your own footage with five observations and one carefully qualified interpretation.','Make a claim the evidence can actually support.'),
lesson('research','research-question','From a topic to a research question','research',['Narrow a topic into an answerable question','Match evidence to the question'],[
['Narrow the field','A topic is an area of interest, such as sound in student films. A research question asks something focused that evidence can address. “How do all audiences respond to film sound?” is too broad for a small project. “How do six consenting classmates describe the clarity of dialogue in two versions of this scene?” defines a manageable group, material and issue. Narrowing is not a loss of ambition; it makes a defensible answer possible.'],
['Choose a method','Close analysis examines the work itself. Interviews explore participants’ accounts. Surveys can collect structured responses, while production research may document a making process. Each method answers some questions better than others. A survey of preferences cannot by itself establish an objective causal effect. If comparing two versions, consider order effects, instructions and other differences between them. Define key terms before collecting information so you do not change the question to fit an appealing result.'],
['Sampling and consent','A small convenience sample can support a modest exploratory report but does not represent every viewer. Explain who participated and how they were recruited. Give people clear information about participation, use and withdrawal, and avoid collecting personal details you do not need. Follow your institution’s requirements before collecting data. An informal classroom exercise should not be presented as formally approved research unless the relevant approval exists.'],
['Plan the evidence','Write the question, method, material, participant approach, analysis plan and likely limitations before beginning. Decide how you will record observations consistently. Pilot the procedure with non-sensitive test material to identify confusing wording or technical problems. A useful outcome may be a revised question rather than a dramatic finding. Keep notes of changes and report them honestly. The strength of a project comes from the fit between its question and evidence, not the size of its claims.']
], 'Broad topic: editing and emotion. Focused question: how do participants describe tension after two different pause lengths in the same original scene? Keep sound and images otherwise consistent and report the small sample limitation.', ['Research question','Method','Sampling'],[q('rq1','A convenience sample represents everyone.',['True','False'],1,'Its selection limits generalization.'),q('rq2','Choose a method based on…',['The question and needed evidence','The trendiest software'],0,'Method must fit what you want to establish.')], 'Write one question, a suitable method, the evidence needed and two limits you expect.','An answerable question sets boundaries before data collection.'),
lesson('research','evidence-citation','Evidence, citations and media literacy','research',['Evaluate the support behind a claim','Distinguish quotation, paraphrase and original analysis'],[
['Trace the claim','A source is useful when it is relevant, credible and actually supports the claim you make. Check author, publication context, date, evidence and the original material behind a summary. A popular post may point to a study without accurately describing it. Whenever practical, follow the reference to the original publication. Do not cite a title you have not checked as though you read and verified its contents.'],
['Use sources transparently','Quotation repeats exact wording and needs clear quotation marks plus a reference. Paraphrase restates an idea in your own structure and language but still needs attribution. A citation is not permission to copy whole passages. Keep notes that separate direct quotation, paraphrase and your own analysis so drafts do not blur them. Use the citation style required by the assignment or journal consistently, and include enough bibliographic detail for the reader to locate the source.'],
['Evidence and media claims','Images, statistics and confident language can all create an impression of authority. Ask what was measured, who was included and whether the conclusion goes beyond the evidence. A correlation does not automatically establish causation. A manipulated image may be useful as an object of analysis but not as unqualified proof of an event. Separate the authenticity of the material from the truth of the interpretation attached to it.'],
['A practical verification habit','Build a claim ledger with four columns: claim, supporting source or observation, exact location, and limitations. Check every borrowed claim before submission. If a source cannot be accessed or verified, revise or remove the claim instead of inventing a reference. Disclose relevant methods and follow the destination’s authorship and tool-use rules. Academic credibility depends on traceable decisions and honest limits, not the appearance of certainty.']
], 'Claim: a shorter pause caused every viewer to feel more tension. Evidence: four of six respondents selected the shorter version. Revision: in this small sample, four respondents reported greater tension; causation and population-wide effects remain unestablished.', ['Citation','Paraphrase','Causation'],[q('ev1','Does paraphrasing remove the need to cite a borrowed idea?',['Yes','No'],1,'Attribution concerns the idea as well as the wording.'),q('ev2','A source should be cited only after checking it supports the claim.',['True','False'],0,'A plausible title is not sufficient evidence.')], 'Create a claim ledger for a short film analysis. Check each borrowed claim against its source.','Make evidence traceable and keep claims proportional to it.')],quiz:[q('rs1','A defensible interpretation begins with…',['Specific evidence','A fabricated quote','A universal formula'],0,'Observable details anchor the argument.'),q('rs2','Which question is focused?',['Why does cinema matter to everyone?','How does offscreen sound guide space in this 60-second scene?','What is all art?'],1,'It defines a manageable object and issue.'),q('rs3','Paraphrased ideas need attribution.',['True','False'],0,'Changing wording does not make the idea yours.'),q('rs4','A small convenience sample permits…',['Limited exploratory observations','Universal audience claims','Automatic causal proof'],0,'Selection and size limit inference.'),q('rs5','If a source cannot be verified, you should…',['Invent page numbers','Revise or remove the unsupported claim','Treat the title as proof'],1,'Traceable evidence is essential.') ]}
];
export const lessons = courses.flatMap(c=>c.lessons);
export const getCourse = (id:string) => courses.find(c=>c.id===id);
export const getLesson = (id:string) => lessons.find(l=>l.id===id);
